CREATE TABLE IF NOT EXISTS strategy_subscriptions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, template_id VARCHAR(255) NOT NULL, symbol VARCHAR(255) NOT NULL, lots INTEGER, intraday BOOLEAN, app_user_id BIGINT, broker_credentials_id BIGINT, source VARCHAR(255), status VARCHAR(255) NOT NULL, last_message VARCHAR(4096), last_evaluation_status VARCHAR(255), generated_trade_request_id BIGINT, created_at TIMESTAMP, updated_at TIMESTAMP, last_evaluated_at TIMESTAMP, completed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS trigger_trade_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, symbol VARCHAR(255), scrip_code INTEGER, exchange VARCHAR(255), instrument_type VARCHAR(255), strike_price DOUBLE PRECISION, option_type VARCHAR(255), expiry VARCHAR(255), quantity BIGINT, lots INTEGER, broker_credentials_id BIGINT, app_user_id BIGINT, entry_price DOUBLE PRECISION, stop_loss DOUBLE PRECISION, target1 DOUBLE PRECISION, target2 DOUBLE PRECISION, target3 DOUBLE PRECISION, trailing_sl DOUBLE PRECISION, tsl_enabled BOOLEAN, use_spot_price BOOLEAN, use_spot_for_entry BOOLEAN, use_spot_for_sl BOOLEAN, use_spot_for_target BOOLEAN, spot_scrip_code INTEGER, intraday BOOLEAN, source VARCHAR(255), broker_product_type VARCHAR(255), opening_rule_reset BOOLEAN, gap_policy_initialized BOOLEAN, gap_protection_enabled BOOLEAN, gap_day_open DOUBLE PRECISION, gap_previous_close DOUBLE PRECISION, gap_stop_loss DOUBLE PRECISION, gap_reentry_count INTEGER, status VARCHAR(255), reason VARCHAR(255), comment VARCHAR(2000), created_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS triggered_trade_setups (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, trigger_request_id BIGINT, symbol VARCHAR(255), scrip_code INTEGER, broker_credentials_id BIGINT, app_user_id BIGINT, exchange VARCHAR(255), instrument_type VARCHAR(255), strike_price DOUBLE PRECISION, option_type VARCHAR(255), expiry VARCHAR(255), quantity BIGINT, lots INTEGER, original_lots INTEGER, target_order_group_id BIGINT, target_stage INTEGER, entry_price DOUBLE PRECISION, actual_entry_price DOUBLE PRECISION, stop_loss DOUBLE PRECISION, target1 DOUBLE PRECISION, target2 DOUBLE PRECISION, target3 DOUBLE PRECISION, trailing_sl DOUBLE PRECISION, tsl_enabled BOOLEAN, use_spot_price BOOLEAN, use_spot_for_entry BOOLEAN, use_spot_for_sl BOOLEAN, use_spot_for_target BOOLEAN, spot_scrip_code INTEGER, order_id VARCHAR(255) UNIQUE, exit_order_id VARCHAR(255) UNIQUE, exit_reason VARCHAR(255), reason VARCHAR(255), comment VARCHAR(2000), intraday BOOLEAN, source VARCHAR(255), broker_product_type VARCHAR(255), gap_protection_enabled BOOLEAN, gap_day_open DOUBLE PRECISION, gap_previous_close DOUBLE PRECISION, gap_stop_loss DOUBLE PRECISION, gap_reentry_count INTEGER, status VARCHAR(255), triggered_at TIMESTAMP, entry_at TIMESTAMP, exited_at TIMESTAMP, exit_price DOUBLE PRECISION, pnl DOUBLE PRECISION, trade_cost DOUBLE PRECISION, effective_pnl DOUBLE PRECISION, exit_order_placed_at TIMESTAMP, exit_claimed_at TIMESTAMP);
ALTER TABLE trigger_trade_requests ADD COLUMN IF NOT EXISTS broker_product_type VARCHAR(255);
ALTER TABLE triggered_trade_setups ADD COLUMN IF NOT EXISTS broker_product_type VARCHAR(255);
CREATE INDEX IF NOT EXISTS idx_strategy_subscriptions_user ON strategy_subscriptions(app_user_id);
CREATE INDEX IF NOT EXISTS idx_trigger_requests_user ON trigger_trade_requests(app_user_id);
CREATE INDEX IF NOT EXISTS idx_triggered_setups_request ON triggered_trade_setups(trigger_request_id);
